content.css:
.eh-hero{display:grid;grid-template-columns:1.1fr 1fr;gap:3rem;align-items:center;padding:3rem 0 4rem}
.eh-kicker{font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;color:var(--color-brand,#0066cc);margin:0 0 1rem;font-weight:600}
.eh-hero h1{font-size:clamp(2.25rem,5vw,3.75rem);line-height:1.05;letter-spacing:-.02em;margin:0 0 1.25rem}
.eh-hero p{font-size:1.125rem;color:var(--color-text-secondary,#555);max-width:32rem;margin:0 0 2rem}
.eh-actions{display:flex;gap:.75rem;flex-wrap:wrap}
.eh-btn{display:inline-block;padding:.85rem 1.5rem;border-radius:var(--radius,6px);font-weight:600;text-decoration:none;border:1px solid var(--color-border,#1a1a1a);color:var(--color-text,#1a1a1a)}
.eh-btn:hover{border-color:var(--color-brand,#0066cc)}
.eh-btn--primary{background:var(--color-brand,#1a1a1a);color:var(--color-on-brand,#fff);border-color:var(--color-brand,#1a1a1a)}
.eh-btn--primary:hover{background:var(--color-brand-hover,var(--color-brand))}
.eh-hero-media img{width:100%;height:auto;aspect-ratio:4/5;max-height:640px;object-fit:cover;border-radius:calc(var(--radius,6px) * 2);display:block;box-shadow:var(--shadow-card,none)}
.eh-usps{display:grid;grid-template-columns:repeat(3,1fr);gap:1.5rem;padding:2rem 0;border-top:1px solid var(--color-border-subtle,#f0f0f0);border-bottom:1px solid var(--color-border-subtle,#f0f0f0);margin-bottom:3rem}
.eh-usp h3::before{content:"";display:inline-block;width:.5rem;height:.5rem;border-radius:50%;background:var(--color-accent,var(--color-brand,#0066cc));margin-inline-end:.5rem;vertical-align:middle}
.eh-usp h3{margin:0 0 .35rem;font-size:1rem}
.eh-usp p{margin:0;color:var(--color-text-secondary,#555);font-size:.95rem}
.eh-section{margin:0 0 4rem}
.eh-section-head{display:flex;align-items:baseline;justify-content:space-between;gap:1rem;margin-bottom:.5rem}
.eh-section-head h2{margin:0;font-size:1.75rem;letter-spacing:-.01em}
.eh-section-head a{color:var(--color-brand,#0066cc);text-decoration:none;font-weight:500}
.eh-story{display:grid;grid-template-columns:1fr 1fr;gap:3rem;align-items:center;background:var(--color-card,var(--color-bg-subtle,#fafafa));color:var(--color-on-card,inherit);border:1px solid var(--color-border-subtle,transparent);border-radius:calc(var(--radius,6px) * 2);padding:2.5rem;margin-bottom:4rem}
.eh-story img{width:100%;height:auto;aspect-ratio:1;object-fit:cover;border-radius:8px;display:block}
.eh-story h2{margin:0 0 1rem;font-size:1.75rem}
.eh-story p{color:var(--color-text-secondary,#555);margin:0 0 1.25rem}
@media(max-width:760px){.eh-hero,.eh-story{grid-template-columns:1fr;gap:1.5rem}.eh-usps{grid-template-columns:1fr;gap:1rem}.eh-hero{padding:1.5rem 0 2.5rem}}

/* store layout shared by the designed pages */
.eh-home,.ec-shop,.ec-cart,.ec-order-page{max-width:var(--wide-width,1200px);margin:0 auto;padding:0 1.5rem}
.ec-product-card__media img{aspect-ratio:4/5;object-fit:cover;background:var(--color-bg-subtle,#f5f5f5)}
.ec-product-card__title a{text-decoration:none;color:var(--color-text,#1a1a1a)}
.ec-product-card__title a:hover{color:var(--color-brand,#0066cc)}
.ec-add-to-cart,.ec-add-to-cart--link{border-radius:6px}
.ec-shop__header{margin-top:2rem}
.ec-cart,.ec-order-page{padding-top:2rem;padding-bottom:4rem}
.ec-cart h1{margin-top:0}
